exports.init = (params, rng) => {
  const ip = params.initialPopulation !== undefined ? params.initialPopulation : (params.initial_population !== undefined ? params.initial_population : 10);
  const K = params.k !== undefined ? params.k : (params.K !== undefined ? params.K : 500);
  const r = params.r !== undefined ? params.r : 0.3;
  const dd = params.densityDependence !== undefined ? params.densityDependence : (params.density_dependence !== undefined ? params.density_dependence : true);
  const visual = Math.min(ip, 300);
  let agents = [];
  for (let i=0;i<visual;i++) {
    agents.push({id:i, x:rng.range(0,1), y:rng.range(0,1), tint:1, sprite:"fish"});
  }
  const initPerCapita = dd ? r*(1 - ip/K) : r;
  const initDensity = ip / K;
  let initBirthPerCapita, initDeathPerCapita;
  if (dd) {
    initBirthPerCapita = (r + 0.08) - (r * 0.6 * initDensity);
    initDeathPerCapita = 0.08 + (r * 0.4 * initDensity);
  } else {
    initBirthPerCapita = r + 0.08;
    initDeathPerCapita = 0.08;
  }
  return {N:ip, agents, births_last: initBirthPerCapita * ip, deaths_last: initDeathPerCapita * ip, perCapitaGrowth:initPerCapita, perCapitaGrowthEarly:initPerCapita, perCapitaSumEarly:initPerCapita, perCapitaCountEarly:1, nextId:visual, stepCount:0};
};
exports.step = (state, params, rng) => {
  const K = params.k !== undefined ? params.k : (params.K !== undefined ? params.K : 500);
  const r = params.r !== undefined ? params.r : 0.3;
  const dd = params.densityDependence !== undefined ? params.densityDependence : (params.density_dependence !== undefined ? params.density_dependence : true);
  let N = state.N;
  if (N <= 0) {
    return {...state, births_last:0, deaths_last:0, perCapitaGrowth:0, stepCount:state.stepCount+1};
  }
  const density = N / K;
  let birthPerCapita, deathPerCapita;
  if (dd) {
    birthPerCapita = (r + 0.08) - (r * 0.6 * density);
    deathPerCapita = 0.08 + (r * 0.4 * density);
  } else {
    birthPerCapita = r + 0.08;
    deathPerCapita = 0.08;
  }
  birthPerCapita = Math.max(0, Math.min(1, birthPerCapita));
  deathPerCapita = Math.max(0, Math.min(1, deathPerCapita));
  const expectedPerCapita = birthPerCapita - deathPerCapita;
  const births = birthPerCapita * N;
  const deaths = deathPerCapita * N;
  let newN = N + births - deaths;
  if (newN < 0) newN = 0;
  newN = Math.round(newN);
  const perCapitaGrowth = expectedPerCapita;
  let perCapitaSumEarly = state.perCapitaSumEarly;
  let perCapitaCountEarly = state.perCapitaCountEarly;
  let perCapitaGrowthEarly = state.perCapitaGrowthEarly;
  if (density < 0.05) {
    perCapitaSumEarly += perCapitaGrowth;
    perCapitaCountEarly += 1;
    perCapitaGrowthEarly = perCapitaSumEarly / perCapitaCountEarly;
  }
  let agents = state.agents.slice();
  const visualTarget = Math.min(newN, 300);
  const currentVisual = agents.length;
  if (visualTarget > currentVisual) {
    for (let i=0;i<visualTarget - currentVisual;i++) {
      agents.push({id: state.nextId + i, x: rng.range(0,1), y: rng.range(0,1), tint:1, sprite:"fish"});
    }
  } else if (visualTarget < currentVisual) {
    agents = agents.slice(0, visualTarget);
  }
  const newDensity = newN / K;
  const tintVal = Math.max(0.25, Math.min(1, 1 - 0.6 * Math.min(1, newDensity)));
  for (let a of agents) {
    a.tint = Math.max(0, Math.min(1, tintVal + rng.range(-0.05, 0.05)));
  }
  return {N:newN, agents, births_last:births, deaths_last:deaths, perCapitaGrowth, perCapitaGrowthEarly, perCapitaSumEarly, perCapitaCountEarly, nextId: state.nextId + Math.max(0, visualTarget - currentVisual), stepCount: state.stepCount + 1};
};
exports.observe = (state, params) => {
  const N = state.N;
  const prevN = N - state.births_last + state.deaths_last;
  const denom = prevN > 0 ? prevN : (N > 0 ? N : 1);
  const birth_rate = state.births_last / denom;
  const death_rate = state.deaths_last / denom;
  const per_capita_growth_rate = state.perCapitaGrowthEarly !== undefined ? state.perCapitaGrowthEarly : state.perCapitaGrowth;
  return {population_size:N, per_capita_growth_rate:per_capita_growth_rate, birth_rate:birth_rate, death_rate:death_rate};
};
exports.view = (state, params) => {
  return {kind:"population", agents:state.agents};
};
